            rows.append(row)
            vals = []
if vals:
    print("WARN leftover vals:", vals, "cur:", cur)

print("表D.1 parsed rows:", len(rows))
# validate structure
from collections import Counter
print("sectors:", Counter(r["sector"] for r in rows))
print("fuels:", Counter(r["fuel"] for r in rows))
print("techs:", Counter(r["tech"] for r in rows))

# sanity spot-check some known rows
for r in rows:
