{"content": "import json, os

base = "/Users/wushuo/Desktop/环境学院论文/固定燃烧源清单经验缺失处置实验/实验结果/04_实验C_规模与资源表现/075%规模/02_火电热力/03_通用工具调用型Agent/R2"
raw = open(os.path.join(base, "scratch_pdf_text.txt"), encoding="utf-8").read().splitlines()

# preprocess: drop page-number artifact lines (pure int right after T/CSES header line)
lines = []
prev = None
for l in raw:
    s = l.strip()
    if s == "T/CSES 144-2024":
        prev = "TCSES"
        continue  # drop header line itself
    if prev == "TCSES" and s.isdigit() and int(s) <= 100:
        prev = None
        continue  # drop printed page number
    prev = None
    lines.append(l)

def is_num(s):
    s = s.strip()
    if not s: return False
    try:
        float(s); return True
    except ValueError:
        return False

def parse_table(start_marker, end_marker, label_sets, nvals, colnames):
    start = next(i for i,l in enumerate(lines) if start_marker in l)
    end = next(i for i,l in enumerate(lines) if end_marker in l)
    seg = lines[start+1:end]
    rows = []
    cur = {}
    vals = []
    for l in seg:
        s = l.strip()
        if not s: continue
        matched_label = False
        for key, lset in label_sets.items():
            if s in lset:
                cur[key] = s
                matched_label = True
                break
        if matched_label: continue
        if is_num(s):
            vals.append(s)
            if len(vals) == nvals:
                row = dict(cur)
                for c, v in zip(colnames, vals):
                    row[c] = v
                rows.append(row)
                vals = []
    if vals:
        print("WARN leftover:", vals, "at", cur)
    return rows

SECTORS = {"电力生产","电力供应","热力生产和供应"}
FUELS = {"煤炭","焦炭","煤矸石","其它焦化产品","焦炉煤气 c","高炉煤气 c","其它煤气 c","天然气 c",
         "液化天然气","液化石油气","炼厂干气","转炉煤气 c","其它气体燃料 c","原油","汽油","煤油","柴油",
         "燃料油","其它液体燃料","石油焦","其它石油制品","石油沥青"}
TECHS = {"煤粉炉","流化床炉","自动炉排层燃炉","手动炉排层燃炉","燃气锅炉","燃油锅炉","不分技术"}
D1 = parse_table("表D.1", "注：a NOx", {"sector":SECTORS,"fuel":FUELS,"tech":TECHS}, 8,
                 ["CO","NOx","SO2","VOCs","PM25","PM10","BC","OC"])
print("表D.1 rows:", len(D1))
for r in D1:
    if r.get("fuel")=="其它石油制品" and r.get("sector")=="热力生产和供应":
        print("last row check:", r)
    if r.get("fuel")=="其它石油制品" and r.get("sector")=="电力生产":
        print("row22 check:", r)
json.dump(D1, open(os.path.join(base, "scratch_table_d1.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)

# ---------------- 表C.1 (sr, ar) ----------------
