GAS_FUELS = {"天然气 c","焦炉煤气 c","高炉煤气 c","转炉煤气 c","其它煤气 c","其它气体燃料 c",
             "液化天然气","液化石油气","炼厂干气"}  # 表D.1注c: 气体燃料系数单位 g/m3
