# 行业类别 -> 表D.1 部门/行业 (电力热力源)
def sector_of(ind_code):
    ind_code = str(ind_code)
    if ind_code in {"4411", "4412", "4417", "4419"}:
        return "电力生产"
    if ind_code == "4430":
        return "热力生产和供应"
    if ind_code == "4420":
        return "电力供应"
    # 采矿业/制造业/燃气供应业等企业的自备电站锅炉: 采用表D.1"电力供应"部门系数
    # (与附录E 表E.7 采矿业和制造业 系数一致)
    return "电力供应"

def nox_capacity_factor(cap_wan_kw):
    """表D.1注b: 电力生产燃煤 NOx 系数与装机容量相关; 装机容量(万千瓦)*10=MW"""
    mw = float(cap_wan_kw) * 10.0
    if mw <= 100.0:
        return 8.96
    if mw < 300.0:
        return 8.19
    return 7.21

POLLUTANTS = ["SO2", "NOx", "CO", "VOC", "PM2.5", "PM10", "BC", "OC", "NH3"]
D1_COL = {"CO": "CO", "NOx": "NOx", "SO2": "SO2", "VOC": "VOCs",
          "PM2.5": "PM25", "PM10": "PM10", "BC": "BC", "OC": "OC"}

def component_factors(sid, comp, fuel_type, amount, unit, sector, row):
    """返回 (factors, params, problems)
       factors: {pollutant: (ef_value, mode, unit)} 仅含可计算的污染物
       params: 参数记录列表
       problems: [(pollutant, reason)] 无法计算的原因
    """
    factors, params, problems = {}, [], []
    d1_fuel = FUEL_MAP.get(fuel_type, None)
    if d1_fuel is None:
        for p in ["SO2", "NOx", "CO", "VOC", "PM2.5", "PM10", "BC", "OC"]:
            problems.append((p, "fuel_factor_unavailable_in_table_d1"))
        return factors, params, problems

    # 燃烧技术确定
    if d1_fuel in COAL_FUELS:
        tech_raw = row.get("电站锅炉燃烧方式") if pd.notna(row.get("电站锅炉燃烧方式")) else None
        tech = TECH_MAP.get(str(tech_raw)) if tech_raw is not None else None
    elif d1_fuel in GAS_FUELS:
        tech = "燃气锅炉"
    else:
        tech = "燃油锅炉"

    if tech is None:
        for p in ["SO2", "NOx", "CO", "VOC", "PM2.5", "PM10", "BC", "OC"]:
            problems.append((p, "combustion_method_unavailable"))
        return factors, params, problems

    d1 = d1_lookup(sector, d1_fuel, tech)
    if d1 is None:
        for p in ["SO2", "NOx", "CO", "VOC", "PM2.5", "PM10", "BC", "OC"]:
            problems.append((p, "no_d1_row_for_fuel_tech"))
        return factors, params, problems

    is_gas = d1_fuel in GAS_FUELS and tech == "燃气锅炉"
    ef_unit = "g/m3" if is_gas else "g/kg"

    # 煤炭类物料衡算参数
    sr = ar = fpm25 = fpm10 = fbc = foc = None
    if d1_fuel in COAL_FUELS:
        c1 = c_lookup(TABLE_C1, sector, tech)
        c2 = c_lookup(TABLE_C2, sector, tech)
        c3 = c_lookup(TABLE_C3, sector, tech)
        if c1 is None or c2 is None or c3 is None:
            for p in ["SO2", "NOx", "CO", "VOC", "PM2.5", "PM10", "BC", "OC"]:
                problems.append((p, "coal_param_row_unavailable"))
            return factors, params, problems
        sr, ar = float(c1["sr"]), float(c1["ar"])
        fpm25, fpm10 = float(c2["fpm25"]), float(c2["fpm10"])
        fbc, foc = float(c3["fbc"]), float(c3["foc"])

    # 含硫量 / 灰分 (燃料X平均收到基)
    s_val = row.get("燃料一平均收到基含硫量") if comp == "F1" else row.get("燃料二平均收到基含硫量")
    s_unit = row.get("燃料一平均收到基含硫量单位") if comp == "F1" else row.get("燃料二平均收到基含硫量单位")
    ash_val = row.get("燃料一平均收到基灰分（%）") if comp == "F1" else row.get("燃料二平均收到基灰分（%）")
    s_num = float(s_val) if pd.notna(s_val) else None
    ash_num = float(ash_val) if pd.notna(ash_val) else None

    # ---- 各污染物产生系数 ----
    # SO2
    if d1["SO2"] == "物料衡算":
        if s_num is None or (s_unit is not None and "%" not in str(s_unit)):
            problems.append(("SO2", "sulfur_content_missing_or_unit_unexpected"))
        else:
            ef = 20.0 * s_num * (1.0 - sr)   # 公式(3): 2*S(g/kg)*(1-sr), S(%)=10*g/kg
            factors["SO2"] = (ef, "material_balance_formula3", ef_unit)
            params.append({"parameter_id": "S_content", "mode": "reported_input", "value": s_num, "unit": "%"})
            params.append({"parameter_id": "sr_bottom_ash_s_ratio", "mode": "table_C1_default", "value": sr, "unit": "fraction"})
    else:
        factors["SO2"] = (float(d1["SO2"]), "table_D1_default", ef_unit)
    # NOx
    if d1["NOx"] == "装机容量b":
        cap = row.get("对应机组装机容量（万千瓦）")
        if pd.notna(cap):
            ef = nox_capacity_factor(float(cap))
            factors["NOx"] = (ef, "table_D1_capacity_note_b", ef_unit)
            params.append({"parameter_id": "unit_capacity", "mode": "reported_input", "value": float(cap), "unit": "万千瓦"})
        else:
            problems.append(("NOx", "capacity_missing_for_nox_factor"))
    else:
        factors["NOx"] = (float(d1["NOx"]), "table_D1_default", ef_unit)
    # CO / VOC
    factors["CO"] = (float(d1["CO"]), "table_D1_default", ef_unit)
    factors["VOC"] = (float(d1["VOCs"]), "table_D1_default", ef_unit)
    # PM2.5 / PM10 / BC / OC
    for p, col in [("PM2.5", "PM25"), ("PM10", "PM10")]:
        if d1[col] == "物料衡算":
            if ash_num is None:
                problems.append((p, "ash_content_missing"))
            else:
                ef = 10.0 * ash_num * (1.0 - ar) * (fpm25 if p == "PM2.5" else fpm10)  # 公式(4)
                factors[p] = (ef, "material_balance_formula4", ef_unit)
        else:
            factors[p] = (float(d1[col]), "table_D1_default", ef_unit)
    if "PM2.5" in factors and d1_fuel in COAL_FUELS:
        ef25 = factors["PM2.5"][0]
        factors["BC"] = (ef25 * fbc, "material_balance_formula5", ef_unit)
        factors["OC"] = (ef25 * foc, "material_balance_formula6", ef_unit)
        params.append({"parameter_id": "Aar_ash_content", "mode": "reported_input", "value": ash_num, "unit": "%"})
        params.append({"parameter_id": "ar_bottom_ash_ratio", "mode": "table_C1_default", "value": ar, "unit": "fraction"})
        params.append({"parameter_id": "f_pm25", "mode": "table_C2_default", "value": fpm25, "unit": "fraction"})
        params.append({"parameter_id": "f_pm10", "mode": "table_C2_default", "value": fpm10, "unit": "fraction"})
        params.append({"parameter_id": "f_bc", "mode": "table_C3_default", "value": fbc, "unit": "fraction"})
        params.append({"parameter_id": "f_oc", "mode": "table_C3_default", "value": foc, "unit": "fraction"})
    elif d1_fuel in COAL_FUELS:
        problems.append(("BC", "pm25_factor_unavailable"))
        problems.append(("OC", "pm25_factor_unavailable"))

    # 记录各污染物EF参数
    for p in ["SO2", "NOx", "CO", "VOC", "PM2.5", "PM10", "BC", "OC"]:
        if p in factors:
            ef, mode, u = factors[p]
            params.append({"parameter_id": f"EF_{p}", "mode": mode, "value": round(ef, 6), "unit": u})

    return factors, params, problems

def build_components(sid, row, sector):
    """构造燃料组件列表: [(comp_id, fuel_type, amount, unit, factors, params, problems)]"""
    comps = []
    for comp, ftype_c, amt_c, unit_c in [
        ("F1", "燃料一类型", "燃料一消耗量", "燃料一消耗量单位"),
        ("F2", "燃料二类型", "燃料二消耗量", "燃料二消耗量单位"),
    ]:
        ftype = row.get(ftype_c)
        amt = row.get(amt_c)
        if pd.isna(ftype) or pd.isna(amt):
            continue
        try:
            amt = float(amt)
        except (TypeError, ValueError):
            continue
        if amt <= 0:
            continue
        unit = row.get(unit_c)
        unit = str(unit) if pd.notna(unit) else ""
        factors, params, problems = component_factors(sid, comp, str(ftype), amt, unit, sector, row)
        comps.append({"comp": comp, "fuel": str(ftype), "amount": amt, "unit": unit,
                      "factors": factors, "params": params, "problems": problems})
    # 其他燃料消耗总量(吨标准煤) 作为独立组件 F3
    oth = row.get("其他燃料消耗总量（吨标准煤）")
    if pd.notna(oth):
        try:
            oth = float(oth)
        except (TypeError, ValueError):
            oth = None
        if oth is not None and oth > 0:
            # 若 F1 已以吨标准煤填报且数值相同(表单自动复填), 不重复
            dup = any(c["comp"] == "F1" and c["unit"] == "吨标准煤" and abs(c["amount"] - oth) < 1e-9 for c in comps)
            if not dup:
                factors, params, problems = component_factors(sid, "F3", "其他燃料", oth, "吨标准煤", sector, row)
                comps.append({"comp": "F3", "fuel": "其他燃料", "amount": oth, "unit": "吨标准煤",
                              "factors": factors, "params": params, "problems": problems})
    return comps

