def match_measure(name):
    """处理工艺名称 -> 表A.1 措施名 (关键词匹配)"""
    n = name
    # 脱硝
    if "低氮燃烧" in n and ("选择性催化还原" in n or "SCR" in n.replace("（", "(")):
        return "低氮燃烧技术+选择性催化还原法"
    if "低氮燃烧" in n and ("选择性非催化还原" in n or "SNCR" in n):
        return "低氮燃烧技术+选择性非催化还原法"
    if "选择性催化还原" in n or "SCR" in n:
        return "选择性催化还原法"
    if "选择性非催化还原" in n or "SNCR" in n:
        return "选择性非催化还原法"
    # 脱硫
    if "石灰石" in n or "石灰/石膏" in n:
        return "石灰石/石膏法"
    if "双碱" in n:
        return "双碱法"
    if "海水" in n:
        return "海水法"
    if "氧化镁" in n:
        return "氧化镁法"
    if "氨法" in n:
        return "氨法"
    if "炉内喷钙" in n or "炉内脱硫" in n:
        return "炉内喷钙法"
    if "烟气循环流化床" in n:
        return "烟气循环流化床法"
    if "旋转喷雾干燥" in n:
        return "旋转喷雾干燥法"
    if "密相干" in n:
        return "密相干法"
    # 除尘
    if "电袋" in n:
        return "电袋复合除尘法"
    if "静电" in n or "电除尘" in n:
        return "高效静电除尘法" if "高效" in n else "普通静电除尘法"
    if "袋式" in n or "布袋" in n or "过滤除尘" in n or "滤芯" in n:
        return "袋式除尘法"
    if "多管" in n or "旋风" in n:
        return "多管旋风除尘法"
    if "重力沉降" in n:
        return "重力沉降法"
    if "惯性" in n:
        return "惯性除尘法"
    if "文丘里" in n or "水膜" in n or "湿式" in n or "湿法除尘" in n or "喷淋" in n or "水浴" in n or "水帘" in n:
        return "湿式除尘法"
    # VOC
    if "蓄热式热力燃烧" in n or "蓄热式催化燃烧" in n:
        return "蓄热式热力燃烧法" if "热力燃烧" in n else "催化燃烧法"
    if "热力燃烧" in n:
        return "热力燃烧"
    if "沸石转轮" in n:
        return "沸石转轮吸附法"
    if "吸附/催化燃烧" in n or "吸附催化" in n:
        return "吸附/催化燃烧法"
    if "催化燃烧" in n:
        return "催化燃烧法"
    if "活性炭" in n or ("吸附" in n and "蒸汽" in n) or "吸附" in n:
        return "活性炭法"
    if "光催化" in n:
        return "光催化"
    if "光解" in n:
        return "光解"
    if "低温等离子体" in n:
        return "低温等离子体"
    if "冷凝" in n:
        return "冷凝法"
    if "生物过滤" in n or "生物滴滤" in n:
        return "生物过滤法"
    return None

# 设施类型缺工艺名称时的缺省措施 (表A.1 "其他X技术")
FACILITY_TYPE_DEFAULT = {
    "脱硫（酸）设施": "其他脱硫技术",
    "脱硝设施": "其他脱硝技术",
    "除尘设施": "其他除尘技术",
    "挥发性有机物治理设施": None,   # 表A.1 无其他VOC技术默认值 -> 0
    "其他废气污染物治理设施": None,
}
PRIMARY_POLLUTANT = {
    "脱硫（酸）设施": ["SO2"],
    "脱硝设施": ["NOx"],
    "除尘设施": ["PM2.5", "PM10", "BC", "OC"],
    "挥发性有机物治理设施": ["VOC"],
    "其他废气污染物治理设施": [],
}
ALL_POLLUTANT_KEYS = ["SO2", "NOx", "VOC", "PM2.5", "PM2.5-10", "BC", "OC"]
A1_KEY = {"SO2": "SO2", "NOx": "NOx", "VOC": "VOCs", "PM2.5": "PM25",
          "PM2.5-10": "PM2510", "BC": "BC", "OC": "OC"}

# 企业级: 电力热力源治理设施 (排放口名称=电站锅炉/燃气轮机排放口)
cf["_port_is_power"] = cf["对应的排放口名称"].astype(str) == "电站锅炉/燃气轮机排放口"
cf_by_ent = {}
for _, r in cf.iterrows():
    cf_by_ent.setdefault(str(r["统一社会信用代码"]), []).append(r)

def control_efficiencies(sid, row):
    """返回 (eta, methods) — eta: {pollutant: 小数去除效率(0-1)}, methods: {pollutant: [措施名]}
       eta 包含 PM2.5 与 PM2.5-10 两组, 供 PM10 细/粗组分使用
    """
    ent = str(row["统一社会信用代码"])
    facilities = [r for r in cf_by_ent.get(ent, []) if r["_port_is_power"]]
    eta = {p: 0.0 for p in ["SO2", "NOx", "VOC", "PM2.5", "PM2.5-10", "BC", "OC"]}
    methods = {p: [] for p in ["SO2", "NOx", "VOC", "PM2.5", "PM2.5-10", "BC", "OC"]}
    measures_used = []

    for r in facilities:
        ftype = str(r["废气治理设施名称"]) if pd.notna(r["废气治理设施名称"]) else ""
        proc = str(r["处理工艺名称"]) if pd.notna(r["处理工艺名称"]) else ""
        reported = r["去除效率（%）"]
        rep = None
        try:
            rep = float(reported)
        except (TypeError, ValueError):
            rep = None

        measure = match_measure(proc) if proc else None
        if measure is None:
            measure = FACILITY_TYPE_DEFAULT.get(ftype)
        if measure is None:
            continue
        if measure not in A1_BY_MEASURE:
            continue
        row_a1 = A1_BY_MEASURE[measure]
        primary = PRIMARY_POLLUTANT.get(ftype, [])
        for pk in ALL_POLLUTANT_KEYS:
            val = float(row_a1[A1_KEY[pk]]) / 100.0
            if pk in primary and rep is not None:
                val = rep / 100.0
            if val > eta[pk]:
                # 该措施对该污染物有效时记录; 同一污染物多措施按串联合并(1-(1-a)(1-b))
                if val > 0 and measure not in methods[pk]:
                    methods[pk].append(measure)
                    measures_used.append((pk, measure, val))
    # 低氮燃烧技术(基102 行字段) — 若治理设施措施中已含低氮燃烧则不重复
    low_nox_flag = str(row.get("是否采用低氮燃烧技术")) if pd.notna(row.get("是否采用低氮燃烧技术")) else "否"
    has_low_nox_measure = any("低氮燃烧" in m for m in methods["NOx"])
    if low_nox_flag == "是" and not has_low_nox_measure:
        methods["NOx"].append("低氮燃烧技术")
        measures_used.append(("NOx", "低氮燃烧技术", 0.22))
    elif low_nox_flag == "是" and has_low_nox_measure:
        measures_used.append(("NOx", "低氮燃烧技术(已含于组合措施)", 0.0))

    # 串联合并
    for pk, items in methods.items():
        comb = 1.0
        for _, m, v in measures_used:
            if m in items:
                comb *= (1.0 - v)
        eta[pk] = 1.0 - comb
    return eta, methods

