# 6. 主流程: 逐源核算
# ----------------------------------------------------------------------------
item_rows = []          # generic_inventory_items.csv 行
decision_rows = []      # source_decisions.csv 行
disposition_rows = []   # generic_source_disposition.csv 行
exceptions = []         # exception 组

reason_codes = {
    "POWER": "b102_power_device",
    "BOILER": "b102_industrial_boiler_device",
    "OUT_OF_SCOPE": "waste_heat_boiler_no_combustion",
}
ITEM_REASON = {
    "calculated": "all_components_factor_available",
    "not_involved_nh3": "standard_no_nh3_factor_for_power",
    "not_involved_target": "not_in_target_scope",
    "not_involved_out": "source_out_of_scope",
}

def fmt(x):
    if x is None:
        return ""
    return f"{x:.6f}".rstrip("0").rstrip(".") if isinstance(x, float) else str(x)

for sid in MANIFEST["candidate_ids"]:
    info = DECIDED[sid]
    row = info["row"]
    decided = info["decided"]
    ind_code = row["行业类别代码"]

    # ---- 决策输出 ----
    if decided == "POWER":
        disposition = "calculated"  # 占位, 下面按核算结果修正
        sector = sector_of(ind_code)
    elif decided == "BOILER":
        disposition = "not_in_target_scope"
    else:
        disposition = "out_of_scope"

    if decided == "POWER":
        sector = sector_of(ind_code)
        comps = build_components(sid, row, sector)
        eta, methods = control_efficiencies(sid, row)

        # 每个污染物的组件级可用性
        item_status = {}
        item_gen = {}
        item_em = {}
        item_comps_missing = {}
        for p in POLLUTANTS:
            if p == "NH3":
                item_status[p] = "not_involved"
                item_reason[p] = ITEM_REASON["not_involved_nh3"]
                item_gen[p] = None
                item_em[p] = None
                continue
            missing = [c["comp"] for c in comps if p not in c["factors"]]
            item_comps_missing[p] = missing
            if comps and not missing:
                gen = 0.0
                for c in comps:
                    ef, mode, u = c["factors"][p]
                    if u == "g/m3":
                        gen += c["amount"] * 1e4 * ef / 1e6          # 万m3 -> m3; g -> t
                    else:
                        gen += c["amount"] * 1e3 * ef / 1e6          # t -> kg; g -> t
                item_status[p] = "calculated"
                item_gen[p] = gen
                if p == "PM10":
                    em = 0.0
                    for c in comps:
                        ef25 = c["factors"]["PM2.5"][0]
                        ef10 = c["factors"]["PM10"][0]
                        u = c["factors"]["PM10"][2]
                        if u == "g/m3":
                            em += c["amount"] * 1e4 / 1e6 * (ef25 * (1 - eta["PM2.5"]) + (ef10 - ef25) * (1 - eta["PM2.5-10"]))
                        else:
                            em += c["amount"] * 1e3 / 1e6 * (ef25 * (1 - eta["PM2.5"]) + (ef10 - ef25) * (1 - eta["PM2.5-10"]))
                    item_em[p] = em
                else:
                    key = p if p != "VOC" else "VOC"
                    item_em[p] = gen * (1 - eta[key])
            else:
                item_status[p] = "information_insufficient"
                item_gen[p] = None
                item_em[p] = None

        if any(s == "calculated" for s in item_status.values()):
            disposition = "calculated"
        elif all(s == "not_involved" for s in item_status.values()):
            disposition = "calculated" if comps and all(p in c["factors"] for c in comps for p in []) else "information_insufficient"
            disposition = "information_insufficient"
        else:
            disposition = "information_insufficient"

        # 记录活动/参数/控制记录 JSON
        for p in POLLUTANTS:
            act_records = []
            par_records = []
            ctl_records = []
            for c in comps:
                act_records.append({"component_id": c["comp"], "value": c["amount"], "unit": c["unit"]})
                for pr in c["params"]:
                    rec = {"component_id": c["comp"]}
                    rec.update(pr)
                    par_records.append(rec)
                # 控制记录
                if p == "PM10":
                    ctl_records.append({
                        "component_id": c["comp"], "method": ";".join(methods["PM2.5"] + methods["PM2.5-10"]) if (methods["PM2.5"] or methods["PM2.5-10"]) else "none",
                        "efficiency": "", "fine_efficiency": fmt(eta["PM2.5"]), "coarse_efficiency": fmt(eta["PM2.5-10"]),
                    })
                elif p == "NH3":
                    ctl_records.append({"component_id": c["comp"], "method": "none", "efficiency": 0,
                                        "fine_efficiency": "", "coarse_efficiency": ""})
                else:
                    key = p if p != "VOC" else "VOC"
                    eff = eta.get(key, 0.0)
                    m = methods.get(key, [])
                    ctl_records.append({"component_id": c["comp"], "method": ";".join(m) if m else "none",
                                        "efficiency": fmt(eff), "fine_efficiency": "", "coarse_efficiency": ""})
            status = item_status[p]
            item_rows.append({
                "source_id": sid, "target": decided,
                "pollutant": p, "status": status,
                "method": calc_method_str(status, p, comps),
                "activity_record_json": json.dumps(act_records, ensure_ascii=False),
                "parameter_record_json": json.dumps(par_records, ensure_ascii=False),
                "control_record_json": json.dumps(ctl_records, ensure_ascii=False),
                "generation_t": fmt(item_gen[p]), "emission_t": fmt(item_em[p]),
                "standard_reference": standard_ref(status, p),
                "reason_code": reason_for_item(status, p, item_comps_missing.get(p, [])),
            })
    else:
        # BOILER / OUT_OF_SCOPE: 不参与本次 POWER 目标核算
        for p in POLLUTANTS:
            item_rows.append({
                "source_id": sid, "target": decided,
                "pollutant": p, "status": "not_involved",
                "method": "N/A",
                "activity_record_json": "[]",
                "parameter_record_json": "[]",
                "control_record_json": "[]",
                "generation_t": "", "emission_t": "",
                "standard_reference": "T/CSES 144-2024 第7章(仅核算电力热力源)",
                "reason_code": ITEM_REASON["not_involved_out"] if decided == "OUT_OF_SCOPE" else ITEM_REASON["not_involved_target"],
            })

    decision_rows.append({
        "source_id": sid, "requested_target": MANIFEST["target"], "decided_target": decided,
        "disposition": disposition, "reason_code": reason_codes[decided],
    })
    disposition_rows.append({
        "source_id": sid, "target": decided, "disposition": disposition,
        "reason_code": reason_codes[decided],
    })

def calc_method_str(status, p, comps):
    if status != "calculated":
        return "N/A"
    modes = set()
    for c in comps:
        if p in c["factors"]:
            modes.add(c["factors"][p][1])
    if "material_balance_formula3" in modes:
        return "物料衡算法(公式3)+产排污系数法(公式2)"
    if any("material_balance_formula4" in m or "material_balance_formula5" in m or "material_balance_formula6" in m for m in modes):
        return "物料衡算法(公式4~6)+产排污系数法(公式2)"
    return "产排污系数法(公式2), EF取自表D.1"

def standard_ref(status, p):
    if status == "calculated":
        return "T/CSES 144-2024 7.2 公式(2), 附录D 表D.1"
    if status == "not_involved":
        return "T/CSES 144-2024 第7章核算范围"
    return "T/CSES 144-2024 附录D 表D.1(无对应系数)"

def reason_for_item(status, p, missing_comps):
    if status == "calculated":
        return ITEM_REASON["calculated"]
    if status == "not_involved":
        return ITEM_REASON["not_involved_nh3"] if p == "NH3" else ITEM_REASON["not_involved_target"]
    # information_insufficient: 汇总缺失组件原因
    return "fuel_factor_unavailable_in_table_d1:" + ",".join(sorted(set(missing_comps)))

# ----------------------------------------------------------------------------
# 7. 异常清单 (根因组)
# ----------------------------------------------------------------------------
# 收集根因统计
root_groups = []
def add_exc(eid, sids, pollutant, root_cause, action):
    root_groups.append({"exception_id": eid, "source_id": sids[0], "pollutant": pollutant,
                        "root_cause": f"{root_cause} (影响{len(sids)}个源)", "action_required": action})

msw_sids, bio_sids, waste_sids, whb_sids, gt_sids, mfg_sids = [], [], [], [], [], []
for sid in MANIFEST["candidate_ids"]:
    info = DECIDED[sid]
    row = info["row"]
    if info["decided"] == "POWER":
        for comp, ftc in [("F1", "燃料一类型"), ("F2", "燃料二类型")]:
            ft = row.get(ftc)
            if pd.notna(ft):
                ft = str(ft)
                if ft == "城市生活垃圾（用于燃料）" and sid not in msw_sids:
                    msw_sids.append(sid)
                if ft in ("生物燃料", "其他燃料") and sid not in bio_sids:
                    bio_sids.append(sid)
                if ft == "工业废料（用于燃料）" and sid not in waste_sids:
                    waste_sids.append(sid)
    if info["decided"] == "OUT_OF_SCOPE":
        whb_sids.append(sid)

add_exc("EX-01", msw_sids, "SO2,NOx,CO,VOC,PM2.5,PM10,BC,OC",
        "电站锅炉以城市生活垃圾为燃料: 表D.1无该燃料系数, 按T/CSES 144-2024第13章属废弃物处理源(生活垃圾焚烧)",
        "由用户按废弃物处理源方法(附录J 表J.1)核算, 或确认从本次固定燃烧源POWER清单中排除")
add_exc("EX-02", bio_sids, "SO2,NOx,CO,VOC,PM2.5,PM10,BC,OC",
        "生物燃料/其他燃料(以吨标准煤计): 表D.1无对应燃料系数",
        "由用户补充生物质/其他燃料产生系数或确认排除")
add_exc("EX-03", waste_sids, "SO2,NOx,CO,VOC,PM2.5,PM10,BC,OC",
        "工业废料(用于燃料): 表D.1无对应燃料系数",
        "由用户确认燃料属性并补充系数, 或按废弃物处理源方法核算")
add_exc("EX-04", whb_sids, "n/a",
        "余热利用锅炉: 不消耗燃料燃烧, 标准系数表(表D.1/表E.7)无该燃烧技术, 判定范围外",
        "由用户确认是否纳入其他源类核算")
add_exc("EX-05", [sid for sid in MANIFEST["candidate_ids"] if DECIDED[sid]["decided"] == "POWER"][:1], "VOC",
        "表D.1中液化天然气/液化石油气/石油焦VOCs产生系数为33(g/kg或g/m3), 数值异常偏大, 疑似标准印刷错误(可能为0.33)",
        "由用户核对T/CSES 144-2024原文并确认VOCs系数取值")
add_exc("EX-06", [sid for sid in MANIFEST["candidate_ids"] if DECIDED[sid]["decided"] == "POWER"][:1], "NH3",
        "电力热力源第7章方法及表D.1均未提供NH3产生系数, 本次NH3项记为not_involved",
        "由用户确认电力热力源NH3是否需核算及核算方法")
add_exc("EX-07", [sid for sid in MANIFEST["candidate_ids"] if DECIDED[sid]["decided"] == "POWER"][:1], "n/a",
        "治理设施缺失处理工艺/去除效率时, 采用附录A 表A.1平均去除效率(按设施类型缺省: 其他脱硫40%/其他脱硝20%/其他除尘10%), 投运率无运行时间数据按1.0假设",
        "由用户补充治理设施运行时间与工艺信息, 修正投运率与效率取值")
add_exc("EX-08", [sid for sid in MANIFEST["candidate_ids"] if DECIDED[sid]["decided"] == "POWER"][:1], "NOx",
        "电站燃气轮机: 表D.1无燃气轮机燃烧技术行, 按同燃料的燃气锅炉系数处理(燃气锅炉为表D.1唯一气体燃烧技术)",
        "由用户确认燃气轮机系数选用")
add_exc("EX-09", [sid for sid in MANIFEST["candidate_ids"] if DECIDED[sid]["decided"] == "POWER"][:1], "n/a",
        "非电力行业企业(采矿业/制造业/燃气供应业等)自备电站锅炉: 采用表D.1'电力供应'部门系数(与附录E 表E.7采矿业和制造业一致)",
        "由用户确认自备电厂源类归属(电力热力源或工业源)")

# ----------------------------------------------------------------------------
# 8. 写出
# ----------------------------------------------------------------------------
def write_csv(name, rows, cols):
    df = pd.DataFrame(rows, columns=cols)
    df.to_csv(os.path.join(OUT, name), index=False, encoding="utf-8-sig")
    return len(df)

n_dec = write_csv("source_decisions.csv", decision_rows,
                  ["source_id", "requested_target", "decided_target", "disposition", "reason_code"])
n_item = write_csv("generic_inventory_items.csv", item_rows,
                   ["source_id", "target", "pollutant", "status", "method",
                    "activity_record_json", "parameter_record_json", "control_record_json",
                    "generation_t", "emission_t", "standard_reference", "reason_code"])
n_disp = write_csv("generic_source_disposition.csv", disposition_rows,
                   ["source_id", "target", "disposition", "reason_code"])
n_exc = write_csv("generic_exception_list.csv",
                  [{"exception_id": g["exception_id"], "source_id": g["source_id"], "pollutant": g["pollutant"],
                    "root_cause": g["root_cause"], "action_required": g["action_required"]} for g in root_groups],
                  ["exception_id", "source_id", "pollutant", "root_cause", "action_required"])

# 状态统计
from collections import Counter
status_counts = Counter(r["status"] for r in item_rows)
target_counts = Counter(r["target"] for r in item_rows)
decision_counts = Counter(r["decided_target"] for r in decision_rows)

# POWER 汇总排放(仅 calculated)
agg = {}
for r in item_rows:
    if r["status"] == "calculated" and r["emission_t"] not in ("", None):
        agg[r["pollutant"]] = agg.get(r["pollutant"], 0.0) + float(r["emission_t"])

summary = {
    "run_id": MANIFEST["run_id"],
    "target": MANIFEST["target"],
    "input_files": {
        "b102_device_fuel_base": B102_PATH,
        "b101_2001_enterprise_shards": [m["path"] for m in MANIFEST["inputs"] if m["role"] == "enterprise_master"],
        "b101_2002_control_facility_base": CF_PATH,
        "source_identity_index": os.path.join(INPUTS, "source_identity_index.json"),
        "method_standard_pdf": os.path.join(INPUTS, "T_CSES_144-2024.pdf"),
    },
    "processed_source_count": len(decision_rows),
    "item_count_total": n_item,
    "status_counts": dict(status_counts),
    "target_counts": dict(target_counts),
    "decision_counts": dict(decision_counts),
    "power_emission_aggregate_t": {k: round(v, 4) for k, v in sorted(agg.items())},
    "output_files": {
        "source_decisions.csv": os.path.join(OUT, "source_decisions.csv"),
        "generic_inventory_items.csv": os.path.join(OUT, "generic_inventory_items.csv"),
        "generic_source_disposition.csv": os.path.join(OUT, "generic_source_disposition.csv"),
        "generic_exception_list.csv": os.path.join(OUT, "generic_exception_list.csv"),
        "generic_run_summary.json": os.path.join(OUT, "generic_run_summary.json"),
    },
    "rules_and_scripts": {
        "method_reference": "T/CSES 144-2024 第7章公式(2)-(6), 附录A 表A.1, 附录C 表C.1-C.3, 附录D 表D.1",
        "decision_rule": "基102行字段: 电站锅炉/燃气轮机编号非空=POWER; 工业锅炉编号非空=BOILER; 设备类型=余热利用锅炉=OUT_OF_SCOPE",
        "sector_rule": "行业类别4411/4412/4417/4419=电力生产; 4430=热力生产和供应; 其余(自备电厂/制造企业)=电力供应(与表E.7一致)",
        "formula_unit_note": "公式(3)~(6)中S与Aar按g/kg燃料(即%×10)代入, 得到g/kg; 气体燃料系数按表D.1注c为g/m3",
        "control_efficiency_rule": "基101-2002去除效率(%)优先; 缺省用表A.1; 多措施串联合并1-(1-a)(1-b); 低氮燃烧22%; 投运率无运行时间数据按1.0",
        "build_script": os.path.abspath(__file__),
        "pdf_parse_scripts": [
            os.path.join(BASE, "scratch_parse_tables2.py"),
            os.path.join(BASE, "scratch_parse_a1.py"),
        ],
    },
    "unresolved_items": [
        "城市生活垃圾/生物燃料/其他燃料/工业废料燃料无表D.1系数 -> 相应源污染物项 information_insufficient(见 generic_exception_list.csv EX-01~EX-03)",
        "余热利用锅炉判定范围外(EX-04)",
        "表D.1 VOCs=33 疑似异常(EX-05)",
        "电力热力源NH3无标准系数 -> not_involved(EX-06)",
        "治理设施投运率缺数据按1.0假设; 缺工艺/效率按表A.1缺省(EX-07)",
        "燃气轮机采用燃气锅炉系数(EX-08)",
        "自备电厂采用'电力供应'部门系数(EX-09)",
    ],
}
with open(os.path.join(OUT, "generic_run_summary.json"), "w", encoding="utf-8") as f:
    json.dump(summary, f, ensure_ascii=False, indent=2)

print("决策行:", n_dec, "| 项行:", n_item, "| 处置行:", n_disp, "| 异常组:", n_exc)
print("状态计数:", dict(status_counts))
print("目标计数:", dict(target_counts))
print("决策计数:", dict(decision_counts))
print("POWER排放汇总(t):", {k: round(v, 3) for k, v in sorted(agg.items())})
