{"content": "#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
固定燃烧源排放清单编制 —— 通用工具调用型 Agent 实验 (C-75-POW-GEN-R2, target=POWER)
方法依据: T/CSES 144-2024《城市大气污染源排放清单编制技术指南》
  第7章(电力热力源): 公式(2) E=A*EF*(1-eta); 公式(3)~(6) 燃煤 SO2/PM2.5/PM10/BC/OC 物料衡算;
  附录A 表A.1(控制措施平均去除效率); 附录C 表C.1~C.3(燃煤参数); 附录D 表D.1(电力热力源产生系数)
输入: run_manifest.json 指定的基102-2002(设备燃料表), 基101-2001(企业表, 供参考),
      基101-2002(治理设施表), source_identity_index.json, T_CSES_144-2024.pdf(已解析为参数JSON)
输出: outputs/source_decisions.csv, outputs/generic_inventory_items.csv,
      outputs/generic_source_disposition.csv, outputs/generic_exception_list.csv,
      outputs/generic_run_summary.json
"""
import json, os
import pandas as pd
from collections import Counter

BASE = os.path.dirname(os.path.abspath(__file__))
INPUTS = os.path.join(BASE, "inputs")
OUT = os.path.join(BASE, "outputs")
os.makedirs(OUT, exist_ok=True)

# ---------------------------------------------------------------------------
# 1. 读取输入
# ---------------------------------------------------------------------------
with open(os.path.join(BASE, "run_manifest.json"), encoding="utf-8") as f:
    MANIFEST = json.load(f)
with open(os.path.join(INPUTS, "source_identity_index.json"), encoding="utf-8") as f:
    IDX = json.load(f)

B102_PATH = os.path.join(INPUTS, "基102-2002_原始结构脱敏输入.xlsx")
CF_PATH = os.path.join(INPUTS, "基101-2002_原始结构脱敏输入.xlsx")

b102 = pd.read_excel(B102_PATH, sheet_name="Sheet1", dtype=object)
cf = pd.read_excel(CF_PATH, sheet_name="Sheet1", dtype=object)

rec_by_sid = {r["source_id"]: r for r in IDX["records"]}
sid_to_iloc = {sid: r["source_row"] - 2 for sid, r in rec_by_sid.items()}
assert set(MANIFEST["candidate_ids"]) == set(sid_to_iloc.keys())
assert len(b102) == 4442 and len(cf) == 8067

# ---------------------------------------------------------------------------
# 2. 参数表 (由 scratch_parse_tables2.py / scratch_parse_a1.py 从PDF解析并人工核对)
# ---------------------------------------------------------------------------
def load_table(fname):
    with open(os.path.join(BASE, fname), encoding="utf-8") as f:
        return json.load(f)

TABLE_D1 = load_table("scratch_table_d1.json")   # 70 rows: 电力生产/电力供应/热力生产和供应 x 燃料 x 燃烧技术
TABLE_C1 = load_table("scratch_table_c1.json")   # 17 rows: sr, ar
TABLE_C2 = load_table("scratch_table_c2.json")   # 17 rows: fpm25, fpm10
TABLE_C3 = load_table("scratch_table_c3.json")   # 16 rows: fbc, foc
TABLE_A1 = load_table("scratch_table_a1.json")   # 74 measures
A1_BY_MEASURE = {r["measure"]: r for r in TABLE_A1}

def d1_lookup(sector, fuel, tech):
    for r in TABLE_D1:
        if r["sector"] == sector and r["fuel"] == fuel and r["tech"] == tech:
            return r
    return None

def c_lookup(tab, sector, tech):
    for r in tab:
        if r.get("source") == "电力热力源" and r.get("dept") == sector and r.get("tech") == tech:
