        return "低氮燃烧技术+选择性催化还原法"
    if "低氮燃烧" in n and ("选择性非催化还原" in n or "SNCR" in n.upper()):
        return "低氮燃烧技术+选择性非催化还原法"
    if "SNCR" in n.upper() and "SCR" in n.upper():
        return "SNCR+SCR"
    if "选择性催化还原" in n or "SCR" in n.upper():
        return "选择性催化还原法"
    if "选择性非催化还原" in n or "SNCR" in n.upper():
        return "选择性非催化还原法"
