PRIMARY_POLLUTANT = {
    "脱硫（酸）设施": ["SO2"],
    "脱硝设施": ["NOx"],
    "除尘设施": ["PM2.5", "PM2.5-10", "BC", "OC"],
    "挥发性有机物治理设施": ["VOC"],
    "其他废气污染物治理设施": [],
}
A1_KEY = {"SO2": "SO2", "NOx": "NOx", "VOC": "VOCs", "PM2.5": "PM25",
          "PM2.5-10": "PM2510", "BC": "BC", "OC": "OC"}
ETA_KEYS = ["SO2", "NOx", "VOC", "PM2.5", "PM2.5-10", "BC", "OC"]

