def control_efficiencies(row):
    """返回 (eta, methods)
       eta: {pollutant: 去除效率(0~1)}, 含 PM2.5 与 PM2.5-10
       methods: {pollutant: [措施名]}
    """
    facilities = [r for r in cf_by_ent.get(str(row["统一社会信用代码"]), []) if r["_port_is_power"]]
    # (pollutant, measure) -> 效率最大值; 相同措施去重, 多措施串联合并
    meas_eff = {k: {} for k in ETA_KEYS}
    for r in facilities:
        ftype = str(r["废气治理设施名称"]) if pd.notna(r["废气治理设施名称"]) else ""
        proc = str(r["处理工艺名称"]) if pd.notna(r["处理工艺名称"]) else ""
        rep = None
        try:
            rep = float(r["去除效率（%）"])
        except (TypeError, ValueError):
            rep = None
        measure = match_measure(proc) if proc else None
        if measure is None:
            measure = FACILITY_TYPE_DEFAULT.get(ftype)
        if measure is None or measure not in A1_BY_MEASURE:
            continue
        measures = [measure]
        if measure == "SNCR+SCR":
            measures = ["选择性非催化还原法", "选择性催化还原法"]
        primary = PRIMARY_POLLUTANT.get(ftype, [])
        for m in measures:
            a1 = A1_BY_MEASURE[m]
            for pk in ETA_KEYS:
                val = float(a1[A1_KEY[pk]]) / 100.0
                if pk in primary and rep is not None:
                    val = rep / 100.0
                if val > 0:
                    meas_eff[pk].setdefault(m, 0.0)
                    meas_eff[pk][m] = max(meas_eff[pk][m], val)
    # 低氮燃烧技术(基102行字段) —— 若治理设施措施已含"低氮燃烧"则不再重复叠加
    low_nox_flag = str(row.get("是否采用低氮燃烧技术")) if pd.notna(row.get("是否采用低氮燃烧技术")) else "否"
    if low_nox_flag == "是" and not any("低氮燃烧" in m for m in meas_eff["NOx"]):
        meas_eff["NOx"].setdefault("低氮燃烧技术", 0.0)
        meas_eff["NOx"]["低氮燃烧技术"] = max(meas_eff["NOx"]["低氮燃烧技术"], 0.22)
    eta = {}
    methods = {}
    for pk in ETA_KEYS:
        comb = 1.0
        for m, v in meas_eff[pk].items():
            comb *= (1.0 - v)
        eta[pk] = 1.0 - comb
        methods[pk] = list(meas_eff[pk].keys())
    return eta, methods

