def fmt(x):
    if x is None:
        return ""
    return f"{x:.6f}".rstrip("0").rstrip(".") if isinstance(x, float) else str(x)

def calc_method_str(status, p, comps):
    if status != "calculated":
        return "N/A"
    modes = set()
    for c in comps:
        if p in c["factors"]:
            modes.add(c["factors"][p][1])
    if "material_balance_formula3" in modes:
        return "物料衡算法(公式3)+产排污系数法(公式2)"
    if modes & {"material_balance_formula4", "material_balance_formula5", "material_balance_formula6"}:
        return "物料衡算法(公式4~6)+产排污系数法(公式2)"
    return "产排污系数法(公式2), EF取自表D.1"

def standard_ref(status):
    if status == "calculated":
        return "T/CSES 144-2024 7.2 公式(2), 附录D 表D.1, 附录A 表A.1"
    if status == "not_involved":
        return "T/CSES 144-2024 第7章电力热力源核算范围"
    return "T/CSES 144-2024 附录D 表D.1(无对应产生系数)"

def reason_for_item(status, p, comps):
    if status == "calculated":
        return "all_components_factor_available"
    if status == "not_involved":
        return "standard_no_nh3_factor_for_power" if p == "NH3" else (
            "source_out_of_scope" if comps is None else "not_in_target_scope")
    reasons = set()
    for c in comps:
        for pp, rc in c["problems"]:
            if pp == p:
                reasons.add(rc)
    return ",".join(sorted(reasons)) if reasons else "factor_unavailable"

