    dev_type = None
    if pd.notna(row["电站锅炉/燃气轮机编号"]):
        dev_type = str(row["电站锅炉/燃气轮机类型"])
        decided = "POWER"
    elif pd.notna(row["工业锅炉编号"]):
        dev_type = str(row["工业锅炉类型"])
        decided = "BOILER"
    else:
        decided = "OUT_OF_SCOPE"
    if dev_type == "余热利用锅炉":
        decided = "OUT_OF_SCOPE"

    reason_decision = {"POWER": "b102_power_device", "BOILER": "b102_industrial_boiler_device",
                       "OUT_OF_SCOPE": "waste_heat_boiler_no_combustion"}[decided]

    if decided == "POWER":
        sector = sector_of(row["行业类别代码"])
        comps = build_components(row, sector)
        eta, methods = control_efficiencies(row)

        item_status, item_gen, item_em, item_missing = {}, {}, {}, {}
        for p in POLLUTANTS:
            if p == "NH3":
                item_status[p], item_gen[p], item_em[p] = "not_involved", None, None
                continue
            missing = [c["comp"] for c in comps if p not in c["factors"]]
            item_missing[p] = missing
            if comps and not missing:
                gen = 0.0
                for c in comps:
                    ef, mode, u = c["factors"][p]
                    gen += (c["amount"] * 1e4 * ef / 1e6) if u == "g/m3" else (c["amount"] * 1e3 * ef / 1e6)
                item_status[p], item_gen[p] = "calculated", gen
                if p == "PM10":
                    em = 0.0
                    for c in comps:
                        ef25, ef10 = c["factors"]["PM2.5"][0], c["factors"]["PM10"][0]
                        u = c["factors"]["PM10"][2]
                        em25 = ef25 * (1 - eta["PM2.5"])
                        emcoarse = (ef10 - ef25) * (1 - eta["PM2.5-10"])
                        em += (c["amount"] * 1e4 / 1e6) * (em25 + emcoarse) if u == "g/m3" else (c["amount"] * 1e3 / 1e6) * (em25 + emcoarse)
                    item_em[p] = em
                else:
                    key = p if p != "VOC" else "VOC"
                    item_em[p] = gen * (1 - eta[key])
            else:
                item_status[p], item_gen[p], item_em[p] = "information_insufficient", None, None

        disposition = "calculated" if any(s == "calculated" for s in item_status.values()) else "information_insufficient"

        for p in POLLUTANTS:
            act_records, par_records, ctl_records = [], [], []
            for c in comps:
                act_records.append({"component_id": c["comp"], "value": c["amount"], "unit": c["unit"]})
                for pr in c["params"]:
                    rec = {"component_id": c["comp"]}
                    rec.update(pr)
                    par_records.append(rec)
                if p == "PM10":
                    ms = list(dict.fromkeys(methods["PM2.5"] + methods["PM2.5-10"]))
                    ctl_records.append({"component_id": c["comp"],
                                        "method": ";".join(ms) if ms else "none",
                                        "efficiency": "", "fine_efficiency": fmt(eta["PM2.5"]),
                                        "coarse_efficiency": fmt(eta["PM2.5-10"])})
                elif p == "NH3":
                    ctl_records.append({"component_id": c["comp"], "method": "none", "efficiency": 0,
                                        "fine_efficiency": "", "coarse_efficiency": ""})
                else:
                    key = p if p != "VOC" else "VOC"
                    eff = eta.get(key, 0.0)
                    ms = methods.get(key, [])
                    ctl_records.append({"component_id": c["comp"], "method": ";".join(ms) if ms else "none",
                                        "efficiency": fmt(eff), "fine_efficiency": "", "coarse_efficiency": ""})
            status = item_status[p]
            item_rows.append({
                "source_id": sid, "target": decided, "pollutant": p, "status": status,
                "method": calc_method_str(status, p, comps),
                "activity_record_json": json.dumps(act_records, ensure_ascii=False),
                "parameter_record_json": json.dumps(par_records, ensure_ascii=False),
                "control_record_json": json.dumps(ctl_records, ensure_ascii=False),
                "generation_t": fmt(item_gen[p]), "emission_t": fmt(item_em[p]),
                "standard_reference": standard_ref(status),
                "reason_code": reason_for_item(status, p, comps if status == "information_insufficient" else None),
            })
    else:
        for p in POLLUTANTS:
            item_rows.append({
                "source_id": sid, "target": decided, "pollutant": p, "status": "not_involved",
                "method": "N/A",
                "activity_record_json": "[]", "parameter_record_json": "[]", "control_record_json": "[]",
                "generation_t": "", "emission_t": "",
                "standard_reference": "T/CSES 144-2024 第7章电力热力源核算范围",
                "reason_code": "source_out_of_scope" if decided == "OUT_OF_SCOPE" else "not_in_target_scope",
            })
        disposition = "out_of_scope" if decided == "OUT_OF_SCOPE" else "not_in_target_scope"

    decision_rows.append({"source_id": sid, "requested_target": MANIFEST["target"],
                          "decided_target": decided, "disposition": disposition,
                          "reason_code": reason_decision})
    disposition_rows.append({"source_id": sid, "target": decided, "disposition": disposition,
                             "reason_code": reason_decision})

