# ---------------------------------------------------------------------------
def first_power():
    return next(sid for sid in MANIFEST["candidate_ids"] if DECIDED_BY_SID[sid] == "POWER")

DECIDED_BY_SID = {r["source_id"]: r["decided_target"] for r in decision_rows}
