        for ftc in ["燃料一类型", "燃料二类型"]:
            ft = row.get(ftc)
            if pd.notna(ft):
                ft = str(ft)
                if ft == "城市生活垃圾（用于燃料）" and sid not in msw_sids:
                    msw_sids.append(sid)
                if ft in ("生物燃料", "其他燃料") and sid not in bio_sids:
                    bio_sids.append(sid)
                if ft == "工业废料（用于燃料）" and sid not in waste_sids:
                    waste_sids.append(sid)
    if DECIDED_BY_SID[sid] == "OUT_OF_SCOPE":
        whb_sids.append(sid)

EX = []
def add_exc(eid, sids, pollutant, root_cause, action):
    EX.append({"exception_id": eid, "source_id": sids[0], "pollutant": pollutant,
               "root_cause": f"{root_cause} (影响{len(sids)}个源)", "action_required": action})

fp = first_power()
